-- Academicstrata database setup. Paste ALL of this into Supabase > SQL Editor > Run.
create table if not exists public.profiles (
  id uuid primary key references auth.users on delete cascade,
  email text,
  role text not null default 'member',
  premium boolean not null default false
);
create table if not exists public.docs (
  id text primary key default gen_random_uuid()::text,
  collection text not null,
  data jsonb not null default '{}',
  uid uuid default auth.uid(),
  created_at timestamptz not null default now()
);
create index if not exists docs_collection_idx on public.docs(collection);
alter table public.profiles enable row level security;
alter table public.docs enable row level security;

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as
$$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin') $$;
create or replace function public.has_premium() returns boolean language sql stable security definer set search_path = public as
$$ select coalesce((select premium from public.profiles where id = auth.uid()), false) $$;

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as
$$ begin insert into public.profiles (id, email) values (new.id, new.email) on conflict do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

drop policy if exists "read own profile" on public.profiles;
create policy "read own profile" on public.profiles for select using (id = auth.uid() or public.is_admin());
drop policy if exists "admin updates profiles" on public.profiles;
create policy "admin updates profiles" on public.profiles for update using (public.is_admin());

drop policy if exists "read content" on public.docs;
create policy "read content" on public.docs for select using (
  collection in ('resources','posts') or public.is_admin() or (collection = 'submissions' and uid = auth.uid()));
drop policy if exists "admin manages docs" on public.docs;
create policy "admin manages docs" on public.docs for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists "members submit files" on public.docs;
create policy "members submit files" on public.docs for insert with check (collection = 'submissions' and auth.uid() is not null and uid = auth.uid());
drop policy if exists "anyone sends messages" on public.docs;
create policy "anyone sends messages" on public.docs for insert with check (collection in ('messages','subscribers'));

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('files','files', false, 20971520, array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "members upload own folder" on storage.objects;
create policy "members upload own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'files' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "read allowed files" on storage.objects;
create policy "read allowed files" on storage.objects for select using (
  bucket_id = 'files' and (
    public.is_admin()
    or (storage.foldername(name))[1] = auth.uid()::text
    or exists (select 1 from public.docs d where d.collection = 'resources' and d.data->>'assetId' = name
               and (coalesce((d.data->>'premium')::boolean, false) = false or public.has_premium()))));
drop policy if exists "delete own or admin files" on storage.objects;
create policy "delete own or admin files" on storage.objects for delete using (
  bucket_id = 'files' and (public.is_admin() or (storage.foldername(name))[1] = auth.uid()::text));

do $$ begin alter publication supabase_realtime add table public.docs; exception when others then null; end $$;

-- Starter blog posts
insert into public.docs (id, collection, data) values ('how-to-improve-in-maths-high-school','posts',$j${"body": "If you want to know how to get better at maths, start with this idea: maths is a skill that grows with the right kind of practice, not a talent that some people are born with. Many high school students feel stuck on topics like algebra, geometry or graphs. The good news is that a few simple methods can make hard topics click. This article shares five proven ways to understand maths and improve your marks.\n\n## Why many students struggle with maths\n\nMaths builds step by step. If one early idea is weak, later topics feel confusing, and confidence drops. Many students also try to memorise steps without understanding why they work, which fails when the question looks different. The solution is to rebuild understanding, practise regularly and learn from mistakes.\n\n## 1. Learn from worked examples\n\nA worked example shows the full thinking process, not just the answer. Read it line by line and ask why each step was chosen. Then cover the solution and try the next step yourself before checking.\n\n- Study one worked example carefully.\n- Try a similar question without help.\n- Compare your method with the example and fix differences.\n\nRepeat until you can solve similar questions on your own.\n\n## 2. Draw it\n\nA quick sketch can turn a confusing question into something clear. Draw a diagram for geometry, a number line for inequalities, a graph for functions, or a simple picture for a word problem. Label what you are given and mark what you need to find. Many hard questions become easy once you can see them.\n\n## 3. Fix the basics first\n\nIf fractions, negative numbers or basic algebra are shaky, everything built on them will wobble. Spend a week revising the basics with easy questions. This can feel slow, but it quickly makes harder topics easier. Our [study guides](#resources) cover core topics step by step.\n\n## 4. Practise a little every day\n\nMaths is like sport or music: regular practice beats occasional long sessions. Ten questions every day work better than one three-hour session on the weekend, because the ideas stay fresh. Mix easy and hard questions so you keep your confidence while you grow. To make practice a habit, use the routines in our guide on [how to study effectively](#post-how-to-study-effectively-high-school).\n\n## 5. Learn from every mistake\n\nWhen you get a question wrong, do not just copy the correct answer. Find the exact line where things went wrong and redo the question from there. Keep a small notebook of common errors, such as sign mistakes, forgotten units or misread questions, and read it before every test. Mistakes are the fastest teachers you have.\n\n## What to do when you feel stuck\n\n- Re-read the question and underline the key words.\n- Write down what you know and what you need to find.\n- Try a simpler version of the problem first.\n- Take a short break and come back with fresh eyes.\n- Ask a teacher or classmate, then try again on your own.\n\n## Maths exam tips\n\nShow all your working, because many marks are given for method even if the final answer is wrong. Check units and signs, and use any extra time to test your answer by substituting it back. Practise with timed past questions before the exam, as explained in our [4-week exam revision plan](#post-how-to-prepare-for-exams-high-school).\n\n## Frequently asked questions\n\n### Is maths really about talent?\n\nNo. Progress in maths comes mainly from good explanations, regular practice and learning from mistakes. Anyone can improve with the right approach.\n\n### How long does it take to improve in maths?\n\nMost students notice better understanding within a few weeks of daily practice, and bigger improvements over a term.\n\n### What should I do if I fail a maths test?\n\nReview the test question by question, list the topics you lost marks on, and revise those topics first. Treat it as a map of what to practise next.\n\n## Final thoughts\n\nHard maths topics become manageable when you understand each step, practise often and learn from errors. Start with one method from this list today. For more help, download a guide from our [Resources page](#resources) or [get in touch](#contact) and tell us which topic you find hardest.", "category": "Subjects", "createdAt": 1792403200000, "summary": "Struggling with maths? Learn five proven ways to understand hard topics, fix mistakes and build confidence for exams.", "thumb": "thumbs/maths-tips.png", "title": "How to Get Better at Maths: 5 Proven Ways to Understand Hard Topics"}$j$::jsonb) on conflict (id) do update set data = excluded.data;
insert into public.docs (id, collection, data) values ('how-to-prepare-for-exams-high-school','posts',$j${"body": "If you are wondering how to prepare for exams without feeling overwhelmed, the answer is a clear plan. Exams feel far less scary when you know what to do each week and why. This four-week revision plan is designed for high school students, and you can adjust it to fit your timetable and subjects.\n\n## Why you need an exam revision plan\n\nWithout a plan, many students revise the topics they enjoy and avoid the ones they find hard. They also leave practice until the last days, when there is no time to fix mistakes. A plan spreads your work across several weeks, makes sure every topic is covered, and leaves time for rest. It also lowers stress, because you always know what comes next.\n\n## Week 1: Map what you need to cover\n\nStart by writing a list of every subject and the topics inside each one. Use your syllabus, class notes or textbook contents page. Next to every topic, mark whether you feel strong, fair or weak. This list becomes your revision map.\n\nThen create a timetable. Give each subject regular slots and give extra time to weak topics. Keep sessions to 30 to 45 minutes and add short breaks. If you need help setting up good routines first, read our guide on [how to study effectively](#post-how-to-study-effectively-high-school).\n\n## Week 2: Tackle your weakest topics\n\nBegin with the topics you marked as weak while your energy is high. For each topic, follow three steps:\n\n- Read a short summary or your class notes.\n- Study a worked example and understand why each step is used.\n- Try several questions without looking at the answers, then check and correct.\n\nUnderstanding must come before speed. If something still does not make sense, write down your question and ask a teacher or classmate. You can also download summaries from our [Resources page](#resources).\n\n## Week 3: Practise past questions\n\nThis is the most valuable week of your revision. Answer past exam questions under timed conditions, as if you were in the real exam. Then mark your work honestly using the mark scheme.\n\nKeep a mistakes notebook. For each lost mark, write whether the cause was a missing fact, a calculation slip, a misread question or poor time use. Patterns will appear quickly, and fixing those patterns can raise your marks faster than learning new content.\n\n## Week 4: Review, refine and rest\n\nIn the final week, go back over your summaries, key formulas and your mistakes notebook. Do short mixed quizzes across subjects. Stop learning big new topics in the last two days, because it only adds stress. Prepare your pens, calculator, ruler, ID and exam timetable the evening before, and go to bed at a normal time.\n\n## What to do on the day of the exam\n\n- Eat a proper breakfast and arrive early.\n- Read every question twice before you answer.\n- Spend a minute planning longer answers.\n- Watch the clock and move on if you are stuck; return later.\n- Use any spare minutes to check your work.\n\n## How to handle exam stress\n\nSome nerves are normal and can even help you focus. Breathe slowly in for four counts and out for six before the paper starts. Remind yourself that you have prepared, and take one question at a time. After each paper, avoid replaying it with friends, and turn your attention to the next subject.\n\n## Frequently asked questions\n\n### When should I start revising for exams?\n\nAbout four weeks before your first paper is a good start for most students. If you have many subjects or a big final exam, start earlier and use a longer version of this plan.\n\n### How many hours a day should I revise?\n\nMost students do well with two to four focused hours on school days and a little more on weekends, with regular breaks. Adjust to your own energy and workload.\n\n### Are past papers really that important?\n\nYes. They show you the style of questions, the time pressure and where you lose marks, which makes them one of the best revision tools.\n\n## Final thoughts\n\nExams reward steady preparation, not last-minute panic. Follow the plan week by week, keep resting, and trust your work. Need study material to begin? Explore our [free guides](#free) or look at our [premium guides](#premium) for in-depth help, and [contact us](#contact) if you have questions.", "category": "Exams", "createdAt": 1792489600000, "summary": "A simple four-week revision plan to prepare for exams, with weekly steps, past-paper tips and an exam-day checklist.", "thumb": "thumbs/exam-prep.png", "title": "How to Prepare for Exams: A 4-Week Revision Plan for High School Students"}$j$::jsonb) on conflict (id) do update set data = excluded.data;
insert into public.docs (id, collection, data) values ('how-to-study-effectively-high-school','posts',$j${"body": "Knowing how to study effectively is one of the most useful skills a high school student can build. Many learners believe good grades come from studying for longer, but research on learning keeps pointing the same way: the method matters more than the number of hours. This guide explains seven proven study habits that you can start using today, with no special equipment and no cost.\n\n## Why the way you study matters\n\nImagine two students who each spend two hours on Biology. The first reads the textbook from start to finish and highlights sentences. The second studies in short blocks, closes the book, writes down what they remember and checks the gaps. The second student will usually remember far more a week later, even though both spent the same time. Effective studying is about making your brain work in ways that build lasting memory.\n\n## 1. Set a clear goal for every session\n\nBefore you open a book, decide what you want to finish. “Revise Chemistry” is too vague. “Learn the three types of chemical bonding and answer five questions” is clear. A specific goal tells you when you are done and keeps you from drifting.\n\n## 2. Study in short, focused blocks\n\nYour attention drops when you work for too long without a break. A popular method is to study for 25 to 30 minutes, rest for five, and take a longer break after four blocks. During each block, work on one task only and keep your phone in another room.\n\n## 3. Use active recall\n\nActive recall means pulling information out of your memory instead of just looking at it again. Close your notes and write down everything you remember about a topic, or answer questions without looking at the answers. It feels harder than re-reading, and that difficulty is exactly what strengthens memory. You can find ready-made practice material in our [free study guides](#free).\n\n## 4. Space out your revision\n\nCramming everything the night before gives weak, short-lived memory. Instead, revisit a topic after one day, then after three days, then after a week. Each return makes the memory stronger. Spacing is also less stressful, because the work is spread across many days.\n\n## 5. Explain it in your own words\n\nTry teaching a topic to a friend, a sibling, or even an empty chair. If you can explain photosynthesis or Pythagoras’ theorem in plain words, you understand it. If you get stuck, you have found the exact point to study again.\n\n## 6. Build a distraction-free study space\n\nChoose a quiet place with good light, keep only the materials you need on the desk, and switch off notifications. If you study on a phone or computer, close social media tabs. A tidy space makes it easier for your mind to settle.\n\n## 7. Protect your sleep, food and movement\n\nSleep is when your brain stores what you learned during the day. Students who stay up very late to revise often remember less than those who sleep well. Eat regular meals, drink water, and take a short walk when you feel tired. These simple habits improve concentration more than any study trick.\n\n## Build a simple weekly timetable\n\nA timetable removes the daily question of what to study. Give every subject a slot, put your hardest subject at the time of day when you feel most awake, and leave space for rest. Before exams, follow a longer plan such as our [four-week exam revision plan](#post-how-to-prepare-for-exams-high-school).\n\n## Common study mistakes to avoid\n\n- Re-reading and highlighting without testing yourself.\n- Studying only the topics you already like.\n- Multitasking with a phone or music with lyrics.\n- Skipping breaks and sleep before a test.\n- Waiting until the last week to start.\n\n## Frequently asked questions\n\n### How many hours should a high school student study each day?\n\nThere is no single answer, because it depends on your class and workload. Many students do well with one to three focused hours on school days, adding more before exams. Quality of study matters more than the number of hours.\n\n### What is the best way to remember what I study?\n\nCombine active recall with spaced revision. Test yourself often, return to topics over several days, and explain ideas aloud.\n\n### How can I stop getting distracted while studying?\n\nPut your phone out of reach, study in short timed blocks, and write a clear goal before each session.\n\n## Final thoughts\n\nYou do not need to change everything at once. Choose one habit this week, practise it daily, and add another when it feels natural. Small, steady changes lead to big improvements. Ready to put these habits into practice? Browse our [Resources page](#resources) for study guides in every subject.", "category": "Study tips", "createdAt": 1792576000000, "summary": "Learn seven proven study habits for high school students, from active recall to better sleep, to remember more in less time.", "thumb": "thumbs/study-habits.png", "title": "How to Study Effectively: 7 Proven Habits for High School Students"}$j$::jsonb) on conflict (id) do update set data = excluded.data;
